    "editorLogoUrl" character varying(255) DEFAULT 'https://images.pix.fr/contenu-formatif/editeur/logo-ministere-education-nationale-et-jeunesse.svg'::character varying NOT NULL,
    "isDisabled" boolean DEFAULT false,
    "internalTitle" character varying(255) DEFAULT NULL::character varying,
    locales text[] DEFAULT '{}'::text[] NOT NULL,
    "deliveryMode" character varying(255),
    program text,
    "registrationRequired" boolean DEFAULT false,
    objectives text[] DEFAULT '{}'::text[]
);


--
-- Name: COLUMN trainings."internalTitle"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.trainings."internalTitle" IS 'Internally used title, only displayed in Pix Admin';


--
-- Name: COLUMN trainings.locales; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.trainings.locales IS 'List of locales for which the training is available.';


--
-- Name: COLUMN trainings."deliveryMode"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.trainings."deliveryMode" IS 'geographical arrangements for the training course';


--
-- Name: COLUMN trainings.program; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.trainings.program IS 'training program';


--
-- Name: COLUMN trainings."registrationRequired"; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.trainings."registrationRequired" IS 'registration requirement for attending the training course';


--
-- Name: COLUMN trainings.objectives; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.trainings.objectives IS 'List of objectives to be achieved during the training course';


