--
-- Name: view-active-organization-learners; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public."view-active-organization-learners" AS
 SELECT id,
    "userId",
    "organizationId",
    "firstName",
    "lastName",
    birthdate,
    "createdAt",
    "updatedAt",
    "preferredLastName",
    "middleName",
    "thirdName",
    "birthCity",
    "birthCityCode",
    "birthProvinceCode",
    "birthCountryCode",
    "MEFCode",
    status,
    "nationalStudentId",
    division,
    email,
    "studentNumber",
    department,
    "educationalTeam",
    "group",
    diploma,
    "nationalApprenticeId",
    sex,
    "isDisabled",
    "deletedAt",
    "deletedBy",
    "certifiableAt",
    "isCertifiable",
    attributes
   FROM public."organization-learners"
  WHERE (("deletedAt" IS NULL) AND ("deletedBy" IS NULL));


